+                    }
+                }
+                else {
+                    return;  // invalid dash found, ignore entire call
+                }
+            }
+
+            if (!allZeros) {
+                int dashlen = dashes.length;
+
+                if ((dashlen & 1) == 0) {
+                    newDashes = Arrays.copyOf(dashes, dashlen);
+                }
+                else {
+                    newDashes = Arrays.copyOf(dashes, dashlen * 2);
+
+                    System.arraycopy(dashes, 0, newDashes, dashlen, dashlen);
+                }
+            }
+        }
