+    private static void assertUsableBuffer(IntBuffer buffer) {
+        com.sun.prism.Image image = com.sun.prism.Image.fromIntArgbPreData(buffer, WIDTH, HEIGHT);
+        SWDrawingContext context = new SWDrawingContext(image, _ -> { });
